  function rubric3(topic, example){
    return [criterion('Explains the relevant technical concept',topic),criterion('Applies the concept accurately to the scenario',example),criterion('Links the mechanism to a concrete consequence','because|therefore|so that|which|redu[c|ce]|prevent|allow|improv|risk|impact|enabl')];
  }
