    const writing15=['Outline TWO software debugging tools that could identify a logic error in an alert-processing algorithm.','Outline TWO validation methods relevant to the journey planner.','Outline TWO methods of securing stored student records.','Outline TWO methods of testing a sensor-processing algorithm.','Outline TWO methods of detecting a checkout logic error.'][i];
    qs.push({n:15,title:'Development documentation and debugging',parts:[{id:'a',...rows(prompt15,dd.items,dd.choices,3,[6,5,3])},{id:'b',...written(writing15,3,65,'A debugger breakpoint can pause execution at a chosen statement so the developer can inspect variables and track an unexpected branch. A logging statement can record intermediate values and decision points while the application processes data, making faulty assumptions visible.',[criterion('Identifies one appropriate tool or method','breakpoint|debugger|logging|log statement|unit test|assert|watch|trace|validation|encryption|access control|integration|test case'),criterion('Explains how the first method works','inspect|step|pause|capture|verify|check|reject|compare|trace|monitor'),criterion('Distinguishes a second useful method and operation','and|another|second|also|whereas|alternatively')])}]});
